function randomPassword(){const a="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$";const x=new Uint32Array(14);crypto.getRandomValues(x);return [...x].map(n=>a[n%a.length]).join("")}
