function toast(msg,type=""){
  const e=$("#toast"); if(!e)return;
  e.textContent=msg; e.className="toast show"+(type?" "+type:"");
  clearTimeout(toast.t); toast.t=setTimeout(()=>{e.className="toast"},3300);
}
