async function system(){
  let health=null;try{health=await adminOp({action:"health"})}catch{}
  const {data:cfg}=await sb.from("system_settings").select("key,value").in("key",["registration","school"]);const reg=cfg?.find(x=>x.key==="registration")?.value||{};const school=cfg?.find(x=>x.key==="school")?.value||{};
  $("#content").innerHTML=`<div class="section-head"><div><h1>ตั้งค่าระบบ</h1><div class="muted">ศูนย์ควบคุมก่อนใช้งานจริง</div></div></div><div class="grid two"><div class="card"><h3>สถานะระบบ</h3><div class="alert ${health?.ok?"success":"error"}">${health?.ok?"Backend พร้อมใช้งาน":"ตรวจ Backend อีกครั้ง"}</div><div class="smalltext">Server time: ${esc(health?.server_time||"-")}</div><div class="smalltext">Profiles: ${health?.counts?.profiles??"-"} • Subjects: ${health?.counts?.subjects??"-"} • Worksheets: ${health?.counts?.worksheets??"-"}</div><button class="btn primary" id="initdemo" style="margin-top:14px">เตรียมชุดทดสอบอัตโนมัติ</button><p class="muted smalltext">สร้างห้องทดสอบ + User2000 + ใบงานทดสอบที่ Publish แล้ว โดยไม่ลบข้อมูลเดิม</p></div><div class="card"><h3>การลงทะเบียน</h3><div class="alert ${reg.enabled?"success":"warn"}">${reg.enabled?"เปิดรับลงทะเบียน":"ปิดรับลงทะเบียน"}</div><form id="regsettings"><div class="checks"><label><input type="checkbox" name="enabled" ${reg.enabled?"checked":""}> เปิดรับลงทะเบียน</label></div><div class="field"><label>เปลี่ยนรหัสลงทะเบียน (เว้นว่าง = ใช้เดิม)</label><input name="registration_code" minlength="6"></div><button class="btn primary">บันทึก</button></form></div></div><div class="card" style="margin-top:14px"><h3>ข้อมูลระบบ</h3><div><b>${esc(school.system_name||"DOC-FULL-NR Smart Worksheet")}</b></div><div class="muted">${esc(school.name||"วิทยาลัยเทคนิคนางรอง")} • ${esc(school.timezone||"Asia/Bangkok")}</div></div>`;
  $("#regsettings").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await adminOp({action:"set_registration",enabled:f.get("enabled")==="on",registration_code:String(f.get("registration_code")||"")});toast("บันทึกการลงทะเบียนแล้ว");system()}catch(err){toast(friendlyError(err),"error")}};
  $("#initdemo").onclick=async()=>{const testPassword=randomPassword();try{const r=await adminOp({action:"initialize_system",test_username:"User2000",test_user_password:testPassword,room_name:"ห้องทดสอบระบบ"});modal(`<div class="modal-header"><div><h3>ชุดทดสอบพร้อมแล้ว</h3></div><button class="btn sm" data-close>✕</button></div><div class="alert success">สร้าง/อัปเดตห้อง ผู้ใช้ และใบงานทดสอบสำเร็จ</div><div class="field"><label>Username ทดสอบ</label><input value="${esc(r.test_username)}" readonly></div><div class="field"><label>Password ทดสอบ</label><input value="${esc(testPassword)}" readonly></div><div class="field"><label>ใบงาน</label><input value="${esc(r.worksheet_title||"")}" readonly></div><div class="row end"><button class="btn" id="savecred">บันทึกข้อมูลทดสอบเป็น TXT</button><button class="btn primary" data-close>พร้อมทดสอบ</button></div>`);$("#savecred").onclick=()=>downloadText("DOC-FULL-NR-TEST-ACCOUNT.txt",`Username: ${r.test_username}\nPassword: ${testPassword}\nใช้สำหรับทดสอบระบบเท่านั้น\n`) }catch(err){toast(friendlyError(err),"error")}};
}
async function profile(){
  $("#content").innerHTML=`<div class="card" style="max-width:780px"><h1>โปรไฟล์</h1><div class="alert"><b>ชื่อผู้ใช้:</b> ${esc(S.profile?.username||"-")} • <b>สิทธิ์:</b> ${esc(S.profile?.role||"user")} • ${S.profile?.approval_status==="approved"&&S.profile?.active!==false?"อนุมัติแล้ว":esc(S.profile?.approval_status||"ปิดใช้งาน")}</div><form id="pf"><div class="form-grid"><div class="field"><label>ชื่อแสดงผล</label><input name="full_name" value="${esc(S.profile?.full_name||"")}"></div><div class="field"><label>อีเมลติดต่อ</label><input name="contact_email" type="email" value="${esc(S.profile?.contact_email||"")}"></div><div class="field"><label>รหัสนักศึกษา</label><input value="${esc(S.profile?.student_code||"")}" disabled></div><div class="field"><label>ห้องเรียน</label><input value="${esc(S.profile?.class_name||"")}" disabled></div></div><button class="btn primary">บันทึกโปรไฟล์</button></form><div class="divider"></div><h3>เปลี่ยนรหัสผ่าน</h3><form id="changepass"><div class="field"><label>รหัสผ่านใหม่ อย่างน้อย 8 ตัว</label><input name="password" type="password" minlength="8" required></div><button class="btn warn">เปลี่ยนรหัสผ่าน</button></form></div>`;
  $("#pf").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const {error}=await sb.from("profiles").update({full_name:String(f.get("full_name")),display_name:String(f.get("full_name")),contact_email:String(f.get("contact_email")||"")||null}).eq("id",uid());if(error)return toast(friendlyError(error),"error");await loadProfile();toast("บันทึกโปรไฟล์แล้ว")};
  $("#changepass").onsubmit=async e=>{e.preventDefault();const p=String(new FormData(e.target).get("password"));try{if(isAdmin())await adminOp({action:"reset_password",user_id:uid(),password:p});else{const {error}=await sb.auth.updateUser({password:p});if(error)throw error}toast("เปลี่ยนรหัสผ่านแล้ว") }catch(err){toast(friendlyError(err),"error")}};
}

async function printWorksheet(id){
  const {data:w,error}=await sb.from("worksheets").select("*,subjects(code,name,color_hex)").eq("id",id).single();if(error)return toast(friendlyError(error),"error");
  const color=w.subjects?.color_hex||"#9A2F42";
  const subjectCode=w.subjects?.code||"";
  const docRef=w.reference_code||`FMAC01-${subjectCode.replace(/[^0-9A-Za-z]/g,"")}`;
  const dueText=w.due_at?new Date(w.due_at).toLocaleDateString("th-TH",{day:"2-digit",month:"2-digit",year:"numeric"}):"____________";
  const maxScore=(w.questions||[]).reduce((n,q)=>n+Number(q.points||0),0)||10;
  const showScore=isAdmin();
  const link=`${location.origin}${location.pathname}?worksheet=${encodeURIComponent(w.id)}`;
  modal(`<div class="no-print row end formal-actions"><button class="btn primary" id="printnow">พิมพ์ / Save PDF</button><button class="btn" data-close>ปิด</button></div>
    <div class="formal-sheet" style="--subject-color:${color}">
      <div class="formal-topline"></div>
      <div class="formal-header">
        <div class="formal-school">
          <img class="formal-logo" src="${NRTECH_LOGO_DATA}" alt="ตราวิทยาลัยเทคนิคนางรอง">
          <div><div class="formal-school-name">วิทยาลัยเทคนิคนางรอง</div><div class="formal-dept">แผนกวิชาคอมพิวเตอร์และเทคโนโลยีสารสนเทศ</div><div class="formal-title">ใบงานปฏิบัติการ <span>(Laboratory Worksheet)</span></div></div>
        </div>
        <div class="formal-docbox">
          <div><span>รหัสเอกสาร</span> <b>FM-AC-01</b></div>
          <div><span>ฉบับที่</span> <b>01</b> <span class="formal-page">หน้า 1/1</span></div>
          <div class="formal-expire"><b>วันหมดอายุใบงาน:</b> ${esc(dueText)}</div>
          <svg id="barcode"></svg>
          <div class="formal-ref">${esc(docRef)}</div>
        </div>
      </div>

      <div class="formal-subject-band">
        <div class="formal-subject-info"><div><b>วิชา ${esc(subjectCode)}</b> &nbsp; ${esc(w.subjects?.name||"")}</div><div class="smalltext">${esc(w.title||"")}</div></div>
        ${showScore?`<div class="formal-score"><b>ผลการประเมิน (Admin)</b><div>คะแนนเต็ม ${maxScore} คะแนน</div><div>คะแนนที่ได้ ______</div><div>ผู้ประเมิน ______</div></div>`:`<div class="formal-score"><b>สถานะงาน</b><div>สำหรับผู้เรียน</div><div>ไม่แสดงคะแนน</div></div>`}
      </div>

      <div class="formal-student-grid">
        <div>ชื่อ-นามสกุล <span class="formal-line"></span></div><div>รหัสประจำตัว <span class="formal-line short"></span></div>
        <div>ระดับชั้น <span class="formal-line short"></span></div><div>วันที่ <span class="formal-line short"></span></div>
      </div>

      <div class="formal-instruction"><b>คำชี้แจง</b> ${esc(w.instructions||"ให้นักศึกษาศึกษาเนื้อหาในหน่วยการเรียนรู้ และตอบคำถามต่อไปนี้ให้ถูกต้องและครบถ้วนตามหลักวิชาการ โดยเขียนด้วยลายมือที่อ่านง่ายและเป็นระเบียบเรียบร้อย")}</div>

      <div class="formal-questions">${(w.questions||[]).map((q,i)=>`<div class="formal-question"><div class="formal-qnum">${i+1}</div><div class="formal-qbody"><div>${esc(q.text)}</div><div class="formal-answer-space"></div></div></div>`).join("")}</div>

      <div class="formal-code-row"><div id="qr"></div><div class="smalltext"><b>QR สำหรับเปิดใบงานออนไลน์</b><br>${esc(docRef)}</div></div>
      <div class="formal-footer">วิทยาลัยเทคนิคนางรอง &nbsp; • &nbsp; แผนกวิชาคอมพิวเตอร์และเทคโนโลยีสารสนเทศ &nbsp; • &nbsp; ${esc(docRef)}</div>
    </div>`,{wide:true});
  if(window.QRCode)new QRCode($("#qr"),{text:link,width:82,height:82});
  try{if(window.JsBarcode)JsBarcode("#barcode",docRef,{format:"CODE128",width:1.15,height:42,displayValue:false,margin:0})}catch{}
  $("#printnow").onclick=()=>{document.body.classList.add("printing");window.print();setTimeout(()=>document.body.classList.remove("printing"),500)};
}

async function paperTokensDialog(wid){
  const ar=await sb.from("worksheet_assignments").select("user_id").eq("worksheet_id",wid);if(ar.error)return toast(friendlyError(ar.error),"error");
  const ids=(ar.data||[]).map(x=>x.user_id);
  if(!ids.length)return toast("ใบงานยังไม่มีผู้เรียนที่ได้รับมอบหมาย กรุณา Publish ก่อน","error");
  const [pr,tr]=await Promise.all([sb.from("profiles").select("id,full_name,student_code,class_name").in("id",ids),sb.from("paper_tokens").select("*").eq("worksheet_id",wid).in("user_id",ids)]);
  if(pr.error||tr.error)return toast(friendlyError(pr.error||tr.error),"error");
  const existing=new Map((tr.data||[]).map(x=>[x.user_id,x]));
  const missing=ids.filter(id=>!existing.has(id)).map(user_id=>({worksheet_id:wid,user_id,code_kind:"qr"}));
  if(missing.length){
    const ir=await sb.from("paper_tokens").insert(missing).select("*");if(ir.error)return toast(friendlyError(ir.error),"error");
    for(const x of ir.data||[])existing.set(x.user_id,x);
  }
  const rows=(pr.data||[]).map(p=>({...p,token:existing.get(p.id)?.token||""}));
  modal(`<div class="modal-header"><div><h2>รหัสงานกระดาษ</h2><div class="muted">แจก Token ให้ผู้เรียนแต่ละคน แล้วผู้เรียนยืนยันในเมนู “ยืนยันงานกระดาษ”</div></div><button class="btn sm" data-close>✕</button></div>
    <div class="row end"><button class="btn green" id="tokencsv">Export CSV</button></div>
    <div class="table-wrap"><table><thead><tr><th>ชื่อ</th><th>รหัส</th><th>ห้อง</th><th>Token</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.full_name||"-")}</td><td>${esc(x.student_code||"-")}</td><td>${esc(x.class_name||"-")}</td><td><code>${esc(x.token)}</code></td></tr>`).join("")}</tbody></table></div>`,{wide:true});
  $("#tokencsv").onclick=()=>downloadCSV([["ชื่อ","รหัสนักศึกษา","ห้อง","Token"],...rows.map(x=>[x.full_name,x.student_code,x.class_name,x.token])],`paper-tokens-${wid}.csv`);
}

// Stable extension bridge for DOC-FULL-NR V14. Only deliberately exposed UI actions
// are placed on window; Supabase secrets and internal state remain module-scoped.
window.DOCNR_BASE = Object.freeze({
  openWorksheet,
  printWorksheet,
  paperTokensDialog
});

init();
